"use strict";
import { useEffect, useState } from "react";
import { Flex, Text, styled } from "ui/src";
const TimerContainer = styled(Flex, {
  position: "relative",
  alignItems: "center",
  justifyContent: "center",
  gap: "$spacing4",
  py: "$spacing8",
  px: "$spacing12",
  // width: '100%',
  borderRadius: "$rounded12",
  backgroundColor: "rgba(3, 210, 110, 0.05)",
  backdropFilter: "blur(10px)",
  borderWidth: 1,
  borderColor: "rgba(3, 210, 110, 0.5)",
  $md: {
    px: "$spacing8"
  },
  $sm: {
    px: "$spacing4"
  }
});
const TimeUnit = styled(Flex, {
  alignItems: "center",
  justifyContent: "center",
  flexDirection: "column",
  gap: "$spacing2",
  minWidth: 60,
  $sm: {
    minWidth: 50
  }
});
const TimeValue = styled(Text, {
  variant: "subheading2",
  color: "$absGreen",
  fontWeight: "$bold",
  fontSize: 24,
  pb: 16,
  $lg: {
    fontSize: 20
  }
});
const TimeLabel = styled(Text, {
  variant: "body3",
  color: "$neutral2",
  textTransform: "uppercase",
  fontSize: 10,
  letterSpacing: 0.5,
  position: "absolute",
  bottom: -3
});
const TimerTitle = styled(Text, {
  variant: "body2",
  color: "$neutral2",
  textAlign: "center",
  mb: "$spacing8"
});
export default function Timer({ endDate, title = "Season ends in" }) {
  const [timeLeft, setTimeLeft] = useState({
    days: 0,
    hours: 0,
    minutes: 0,
    seconds: 0
  });
  useEffect(() => {
    const calculateTimeLeft = () => {
      const now = (/* @__PURE__ */ new Date()).getTime();
      const end = endDate.getTime();
      const difference = end - now;
      if (difference > 0) {
        const days = Math.floor(difference / (1e3 * 60 * 60 * 24));
        const hours = Math.floor(difference % (1e3 * 60 * 60 * 24) / (1e3 * 60 * 60));
        const minutes = Math.floor(difference % (1e3 * 60 * 60) / (1e3 * 60));
        const seconds = Math.floor(difference % (1e3 * 60) / 1e3);
        setTimeLeft({ days, hours, minutes, seconds });
      } else {
        setTimeLeft({ days: 0, hours: 0, minutes: 0, seconds: 0 });
      }
    };
    calculateTimeLeft();
    const timer = setInterval(calculateTimeLeft, 1e3);
    return () => clearInterval(timer);
  }, [endDate]);
  const formatTime = (value) => value.toString().padStart(2, "0");
  const dateTime = [
    {
      value: timeLeft.days,
      unit: "days"
    },
    {
      value: timeLeft.hours,
      unit: "hours"
    },
    {
      value: timeLeft.minutes,
      unit: "minutes"
    },
    {
      value: timeLeft.seconds,
      unit: "seconds"
    }
  ];
  return <Flex alignItems="center" justifyContent="center" flexDirection="column">
      {title && <TimerTitle>{title}</TimerTitle>}
      <TimerContainer row>
        {dateTime.map((item, index) => <Flex row>
            <TimeUnit key={item.unit}>
              <TimeValue>{formatTime(item.value)}</TimeValue>
              <TimeLabel>{item.unit}</TimeLabel>
            </TimeUnit>
            {index < 3 && <Text color={"$neutral2"}>:</Text>}
          </Flex>)}
      </TimerContainer>
    </Flex>;
}
